// ─────────────────────────────────────────
// CSV出力の共通ヘルパー
// ─────────────────────────────────────────

// 値をCSVの1フィールドとして安全な形にする（RFC 4180 準拠）。
// カンマ・改行・ダブルクォートを含む場合のみ全体をクォートし、内部の " は "" へ置換する。
function csvCell(value) {
  // { raw: '...' } を渡した場合はエスケープせずそのまま出す。
  // 印刷向形式の ="12/24"（Excelに日付変換させないための記法）用。
  if (value && typeof value === 'object' && typeof value.raw === 'string') return value.raw;
  const v = value == null ? '' : String(value);
  return /[",\r\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v;
}

// 1行分を組み立てる。行末は RFC 4180 に合わせて CRLF。
function csvRow(cells) {
  return cells.map(csvCell).join(',') + '\r\n';
}

// Excel が日付として解釈でき、文字列ソートも崩れない形式にする。
function csvDate(ts) {
  const d = new Date(ts);
  const p2 = (n) => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate());
}

// memberId（無ければ氏名）でメンバーを引く。学年・性別・期の補完に使う。
function findMemberInfo(archer, memberList, alumniList, normalizeName) {
  const all = [].concat(memberList || [], alumniList || []);
  const nm = normalizeName(archer.name || '');
  return all.find(function (m) {
    return (archer.memberId && m.id === archer.memberId) || (m.name && normalizeName(m.name) === nm);
  }) || null;
}

